def parse_json(json_str: str):
    """
    Parse a JSON string according to RFC 8259 without using the built‑in json module
    or eval. Returns the corresponding Python data structure or raises ValueError
    on any syntax error.
    """
    import re

    class _Parser:
        def __init__(self, s):
            self.s = s
            self.i = 0
            self.n = len(s)

        # ---------- public ----------
        def parse(self):
            self._skip_ws()
            value = self._parse_value()
            self._skip_ws()
            if self.i != self.n:
                self._error("Extra data after valid JSON")
            return value

        # ---------- helpers ----------
        def _peek(self):
            return self.s[self.i] if self.i < self.n else ''

        def _next(self):
            ch = self._peek()
            self.i += 1
            return ch

        def _skip_ws(self):
            while self.i < self.n and self.s[self.i] in ' \t\n\r':
                self.i += 1

        def _error(self, msg):
            raise ValueError(f"{msg} at position {self.i}")

        # ---------- value ----------
        def _parse_value(self):
            ch = self._peek()
            if ch == '"':
                return self._parse_string()
            if ch == '{':
                return self._parse_object()
            if ch == '[':
                return self._parse_array()
            if ch in '-0123456789':
                return self._parse_number()
            if self.s.startswith('true', self.i):
                self.i += 4
                return True
            if self.s.startswith('false', self.i):
                self.i += 5
                return False
            if self.s.startswith('null', self.i):
                self.i += 4
                return None
            self._error("Unexpected character while parsing value")

        # ---------- object ----------
        def _parse_object(self):
            obj = {}
            self.i += 1                     # skip '{'
            self._skip_ws()
            if self._peek() == '}':         # empty object
                self.i += 1
                return obj
            while True:
                self._skip_ws()
                if self._peek() != '"':
                    self._error("Object keys must be strings")
                key = self._parse_string()
                self._skip_ws()
                if self._next() != ':':
                    self._error("Missing ':' after object key")
                self._skip_ws()
                val = self._parse_value()
                obj[key] = val
                self._skip_ws()
                ch = self._next()
                if ch == '}':
                    break
                if ch != ',':
                    self._error("Expected ',' or '}' in object")
            return obj

        # ---------- array ----------
        def _parse_array(self):
            arr = []
            self.i += 1                     # skip '['
            self._skip_ws()
            if self._peek() == ']':         # empty array
                self.i += 1
                return arr
            while True:
                self._skip_ws()
                arr.append(self._parse_value())
                self._skip_ws()
                ch = self._next()
                if ch == ']':
                    break
                if ch != ',':
                    self._error("Expected ',' or ']' in array")
            return arr

        # ---------- string ----------
        _ESCAPE_MAP = {
            '"': '"',
            '\\': '\\',
            '/': '/',
            'b': '\b',
            'f': '\f',
            'n': '\n',
            'r': '\r',
            't': '\t',
        }

        def _parse_string(self):
            self.i += 1                     # skip opening quote
            start = self.i
            result = []
            while True:
                if self.i >= self.n:
                    self._error("Unterminated string")
                ch = self.s[self.i]
                if ch == '"':
                    # end of string
                    result.append(self.s[start:self.i])
                    self.i += 1
                    return ''.join(result)
                if ch == '\\':
                    # flush pending literal part
                    result.append(self.s[start:self.i])
                    self.i += 1
                    if self.i >= self.n:
                        self._error("Unterminated escape sequence")
                    esc = self.s[self.i]
                    if esc in self._ESCAPE_MAP:
                        result.append(self._ESCAPE_MAP[esc])
                        self.i += 1
                    elif esc == 'u':
                        # Unicode escape \uXXXX
                        self.i += 1
                        hex_digits = self.s[self.i:self.i+4]
                        if len(hex_digits) != 4 or not re.fullmatch(r'[0-9a-fA-F]{4}', hex_digits):
                            self._error("Invalid Unicode escape")
                        result.append(chr(int(hex_digits, 16)))
                        self.i += 4
                    else:
                        self._error(f"Invalid escape character '\\{esc}'")
                    start = self.i
                elif ord(ch) < 0x20:
                    self._error("Control character in string")
                else:
                    self.i += 1

        # ---------- number ----------
        _NUMBER_RE = re.compile(r'-?(0|[1-9]\d*)(\.\d+)?([eE][+-]?\d+)?')

        def _parse_number(self):
            m = self._NUMBER_RE.match(self.s, self.i)
            if not m:
                self._error("Invalid number")
            num_str = m.group(0)
            self.i = m.end()
            # Decide int vs float
            if '.' in num_str or 'e' in num_str or 'E' in num_str:
                try:
                    return float(num_str)
                except ValueError:
                    self._error("Invalid float literal")
            else:
                try:
                    return int(num_str)
                except ValueError:
                    self._error("Invalid integer literal")

    return _Parser(json_str).parse()

def parse_json(json_str: str):
    """
    Minimal JSON parser (RFC 8259) without using the built‑in json module or eval().
    Returns the corresponding Python data structure or raises ValueError on malformed input.
    """
    import re

    WHITESPACE = re.compile(r'\s*', re.ASCII)

    class Parser:
        def __init__(self, s: str):
            self.s = s
            self.i = 0
            self.n = len(s)

        def error(self, msg: str):
            raise ValueError(f'Error at position {self.i}: {msg}')

        def peek(self):
            return self.s[self.i] if self.i < self.n else ''

        def consume(self, expected: str = None):
            if self.i >= self.n:
                self.error('Unexpected end of input')
            ch = self.s[self.i]
            if expected and ch != expected:
                self.error(f"Expected '{expected}' but got '{ch}'")
            self.i += 1
            return ch

        def skip_ws(self):
            m = WHITESPACE.match(self.s, self.i)
            self.i = m.end()

        def parse(self):
            self.skip_ws()
            value = self.parse_value()
            self.skip_ws()
            if self.i != self.n:
                self.error('Trailing characters')
            return value

        # ---------- value ----------
        def parse_value(self):
            self.skip_ws()
            ch = self.peek()
            if ch == '"':
                return self.parse_string()
            if ch == '{':
                return self.parse_object()
            if ch == '[':
                return self.parse_array()
            if ch in '-0123456789':
                return self.parse_number()
            if self.s.startswith('true', self.i):
                self.i += 4
                return True
            if self.s.startswith('false', self.i):
                self.i += 5
                return False
            if self.s.startswith('null', self.i):
                self.i += 4
                return None
            self.error('Invalid value')

        # ---------- object ----------
        def parse_object(self):
            obj = {}
            self.consume('{')
            self.skip_ws()
            if self.peek() == '}':
                self.consume('}')
                return obj
            while True:
                self.skip_ws()
                if self.peek() != '"':
                    self.error('Object keys must be strings')
                key = self.parse_string()
                self.skip_ws()
                self.consume(':')
                self.skip_ws()
                val = self.parse_value()
                obj[key] = val
                self.skip_ws()
                ch = self.peek()
                if ch == '}':
                    self.consume('}')
                    break
                if ch == ',':
                    self.consume(',')
                else:
                    self.error("Expected ',' or '}' in object")
            return obj

        # ---------- array ----------
        def parse_array(self):
            arr = []
            self.consume('[')
            self.skip_ws()
            if self.peek() == ']':
                self.consume(']')
                return arr
            while True:
                self.skip_ws()
                arr.append(self.parse_value())
                self.skip_ws()
                ch = self.peek()
                if ch == ']':
                    self.consume(']')
                    break
                if ch == ',':
                    self.consume(',')
                else:
                    self.error("Expected ',' or ']' in array")
            return arr

        # ---------- string ----------
        def parse_string(self):
            self.consume('"')
            sb = []
            while True:
                if self.i >= self.n:
                    self.error('Unterminated string')
                ch = self.consume()
                if ch == '"':
                    break
                if ch == '\\':
                    esc = self.consume()
                    if esc == '"':
                        sb.append('"')
                    elif esc == '\\':
                        sb.append('\\')
                    elif esc == '/':
                        sb.append('/')
                    elif esc == 'b':
                        sb.append('\b')
                    elif esc == 'f':
                        sb.append('\f')
                    elif esc == 'n':
                        sb.append('\n')
                    elif esc == 'r':
                        sb.append('\r')
                    elif esc == 't':
                        sb.append('\t')
                    elif esc == 'u':
                        hex_digits = self.s[self.i:self.i+4]
                        if len(hex_digits) < 4 or not all(c in '0123456789abcdefABCDEF' for c in hex_digits):
                            self.error('Invalid \\u escape')
                        code_point = int(hex_digits, 16)
                        sb.append(chr(code_point))
                        self.i += 4
                    else:
                        self.error(f'Invalid escape character \\{esc}')
                elif ord(ch) < 0x20:
                    self.error('Control character in string')
                else:
                    sb.append(ch)
            return ''.join(sb)

        # ---------- number ----------
        def parse_number(self):
            start = self.i
            ch = self.peek()
            if ch == '-':
                self.consume('-')
                ch = self.peek()
            if ch == '0':
                self.consume('0')
            elif '1' <= ch <= '9':
                while self.peek() and self.peek().isdigit():
                    self.consume()
            else:
                self.error('Invalid number')
            # fraction
            if self.peek() == '.':
                self.consume('.')
                if not self.peek().isdigit():
                    self.error('Fraction part requires at least one digit')
                while self.peek() and self.peek().isdigit():
                    self.consume()
            # exponent
            if self.peek() in ('e', 'E'):
                self.consume()
                if self.peek() in ('+', '-'):
                    self.consume()
                if not self.peek().isdigit():
                    self.error('Exponent requires at least one digit')
                while self.peek() and self.peek().isdigit():
                    self.consume()
            num_str = self.s[start:self.i]
            try:
                if '.' in num_str or 'e' in num_str or 'E' in num_str:
                    return float(num_str)
                else:
                    return int(num_str)
            except ValueError:
                self.error('Number conversion failed')

    return Parser(json_str).parse()

def parse_json(json_str: str):
    """
    Parse a JSON string according to RFC 8259 without using the built‑in json module
    or eval.  Returns the corresponding Python data structure (dict, list, str,
    int, float, bool, None).  Raises ValueError on any syntax error.
    """
    import re

    # Regular expression for a JSON number (RFC 8259 §6)
    _NUMBER_RE = re.compile(r'-?(?:0|[1-9]\d*)(?:\.\d+)?(?:[eE][+-]?\d+)?\b')

    class _Parser:
        def __init__(self, s: str):
            self.s = s
            self.i = 0
            self.n = len(s)

        # ---------- public entry ----------
        def parse(self):
            self._skip_ws()
            value = self._parse_value()
            self._skip_ws()
            if self.i != self.n:
                self._error("Extra data after valid JSON value")
            return value

        # ---------- low‑level helpers ----------
        def _peek(self):
            return self.s[self.i] if self.i < self.n else ''

        def _consume(self, expected: str = None):
            if self.i >= self.n:
                self._error("Unexpected end of input")
            ch = self.s[self.i]
            if expected and ch != expected:
                self._error(f"Expected '{expected}' but got '{ch}'")
            self.i += 1
            return ch

        def _skip_ws(self):
            while self.i < self.n and self.s[self.i] in ' \t\n\r':
                self.i += 1

        def _error(self, msg: str):
            raise ValueError(f"{msg} at position {self.i}")

        # ---------- value ----------
        def _parse_value(self):
            self._skip_ws()
            ch = self._peek()
            if ch == '"':
                return self._parse_string()
            if ch == '{':
                return self._parse_object()
            if ch == '[':
                return self._parse_array()
            if ch in '-0123456789':
                return self._parse_number()
            if self.s.startswith('true', self.i):
                self.i += 4
                return True
            if self.s.startswith('false', self.i):
                self.i += 5
                return False
            if self.s.startswith('null', self.i):
                self.i += 4
                return None
            self._error(f"Unexpected character '{ch}'")

        # ---------- object ----------
        def _parse_object(self):
            obj = {}
            self._consume('{')
            self._skip_ws()
            if self._peek() == '}':
                self._consume('}')
                return obj
            while True:
                self._skip_ws()
                if self._peek() != '"':
                    self._error("Object keys must be strings")
                key = self._parse_string()
                self._skip_ws()
                self._consume(':')
                self._skip_ws()
                value = self._parse_value()
                obj[key] = value
                self._skip_ws()
                ch = self._peek()
                if ch == '}':
                    self._consume('}')
                    break
                if ch == ',':
                    self._consume(',')
                    continue
                self._error("Expected ',' or '}' in object")
            return obj

        # ---------- array ----------
        def _parse_array(self):
            arr = []
            self._consume('[')
            self._skip_ws()
            if self._peek() == ']':
                self._consume(']')
                return arr
            while True:
                self._skip_ws()
                arr.append(self._parse_value())
                self._skip_ws()
                ch = self._peek()
                if ch == ']':
                    self._consume(']')
                    break
                if ch == ',':
                    self._consume(',')
                    continue
                self._error("Expected ',' or ']' in array")
            return arr

        # ---------- string ----------
        def _parse_string(self):
            self._consume('"')
            sb = []
            while True:
                if self.i >= self.n:
                    self._error("Unterminated string")
                ch = self._consume()
                if ch == '"':
                    break
                if ch == '\\':
                    esc = self._consume()
                    if esc == '"':
                        sb.append('"')
                    elif esc == '\\':
                        sb.append('\\')
                    elif esc == '/':
                        sb.append('/')
                    elif esc == 'b':
                        sb.append('\b')
                    elif esc == 'f':
                        sb.append('\f')
                    elif esc == 'n':
                        sb.append('\n')
                    elif esc == 'r':
                        sb.append('\r')
                    elif esc == 't':
                        sb.append('\t')
                    elif esc == 'u':
                        # Expect exactly four hex digits
                        hex_digits = self.s[self.i:self.i+4]
                        if len(hex_digits) != 4 or not all(c in "0123456789abcdefABCDEF" for c in hex_digits):
                            self._error("Invalid Unicode escape")
                        code_point = int(hex_digits, 16)
                        sb.append(chr(code_point))
                        self.i += 4
                    else:
                        self._error(f"Invalid escape character '\\{esc}'")
                elif ord(ch) < 0x20:
                    self._error("Control characters must be escaped in strings")
                else:
                    sb.append(ch)
            return ''.join(sb)

        # ---------- number ----------
        def _parse_number(self):
            start = self.i
            # Find the longest prefix that matches the number regex
            while self.i < self.n and self.s[self.i] not in ' \t\n\r,]}':
                self.i += 1
            num_str = self.s[start:self.i]
            if not _NUMBER_RE.fullmatch(num_str):
                self._error(f"Invalid number '{num_str}'")
            # Convert to int if possible, else float
            if '.' in num_str or 'e' in num_str or 'E' in num_str:
                return float(num_str)
            else:
                return int(num_str)

    return _Parser(json_str).parse()

def parse_json(json_str: str):
    """
    Parse a JSON string according to RFC 8259 without using the built‑in json module
    or eval.  Returns the corresponding Python data structure (dict, list, str,
    int, float, bool, None).  Raises ValueError on any syntax error.
    """
    # --------------------------------------------------------------------- #
    # Helper class that holds the source string and a mutable cursor index.
    # --------------------------------------------------------------------- #
    class _Parser:
        def __init__(self, s: str):
            self.s = s
            self.i = 0
            self.n = len(s)

        # --------------------------------------------------------------- #
        # Public entry point
        # --------------------------------------------------------------- #
        def parse(self):
            self._skip_ws()
            value = self._parse_value()
            self._skip_ws()
            if self.i != self.n:
                self._error("Extra data after valid JSON value")
            return value

        # --------------------------------------------------------------- #
        # Core parsing functions
        # --------------------------------------------------------------- #
        def _parse_value(self):
            self._skip_ws()
            if self.i >= self.n:
                self._error("Unexpected end of input while expecting a value")

            ch = self.s[self.i]

            if ch == '"':
                return self._parse_string()
            if ch == '{':
                return self._parse_object()
            if ch == '[':
                return self._parse_array()
            if ch in '-0123456789':
                return self._parse_number()
            if self.s.startswith("true", self.i):
                self.i += 4
                return True
            if self.s.startswith("false", self.i):
                self.i += 5
                return False
            if self.s.startswith("null", self.i):
                self.i += 4
                return None

            self._error(f"Invalid value starting with character {ch!r}")

        # --------------------------------------------------------------- #
        def _parse_object(self):
            # assumes current char is '{'
            self.i += 1  # consume '{'
            obj = {}
            self._skip_ws()
            if self._peek() == '}':
                self.i += 1
                return obj

            while True:
                self._skip_ws()
                if self._peek() != '"':
                    self._error("Object keys must be strings")
                key = self._parse_string()
                self._skip_ws()
                if self._peek() != ':':
                    self._error("Missing ':' after object key")
                self.i += 1  # consume ':'
                self._skip_ws()
                value = self._parse_value()
                obj[key] = value
                self._skip_ws()
                ch = self._peek()
                if ch == '}':
                    self.i += 1
                    break
                if ch != ',':
                    self._error("Expected ',' or '}' in object")
                self.i += 1  # consume ','
            return obj

        # --------------------------------------------------------------- #
        def _parse_array(self):
            # assumes current char is '['
            self.i += 1  # consume '['
            arr = []
            self._skip_ws()
            if self._peek() == ']':
                self.i += 1
                return arr

            while True:
                self._skip_ws()
                arr.append(self._parse_value())
                self._skip_ws()
                ch = self._peek()
                if ch == ']':
                    self.i += 1
                    break
                if ch != ',':
                    self._error("Expected ',' or ']' in array")
                self.i += 1  # consume ','
            return arr

        # --------------------------------------------------------------- #
        def _parse_string(self):
            # assumes current char is '"'
            self.i += 1  # skip opening quote
            start = self.i
            result = []
            while self.i < self.n:
                ch = self.s[self.i]
                if ch == '"':
                    # end of string
                    self.i += 1
                    return ''.join(result)
                if ch == '\\':
                    # escape sequence
                    self.i += 1
                    if self.i >= self.n:
                        self._error("Unterminated escape sequence in string")
                    esc = self.s[self.i]
                    if esc == '"':
                        result.append('"')
                    elif esc == '\\':
                        result.append('\\')
                    elif esc == '/':
                        result.append('/')
                    elif esc == 'b':
                        result.append('\b')
                    elif esc == 'f':
                        result.append('\f')
                    elif esc == 'n':
                        result.append('\n')
                    elif esc == 'r':
                        result.append('\r')
                    elif esc == 't':
                        result.append('\t')
                    elif esc == 'u':
                        # Unicode escape: exactly four hex digits
                        hex_digits = self.s[self.i + 1:self.i + 5]
                        if len(hex_digits) != 4 or not all(c in "0123456789abcdefABCDEF" for c in hex_digits):
                            self._error("Invalid \\uXXXX escape")
                        code_point = int(hex_digits, 16)
                        result.append(chr(code_point))
                        self.i += 4
                    else:
                        self._error(f"Invalid escape character '\\{esc}'")
                elif ord(ch) < 0x20:
                    self._error("Control characters not allowed in JSON strings")
                else:
                    result.append(ch)
                self.i += 1

            self._error("Unterminated string literal")

        # --------------------------------------------------------------- #
        def _parse_number(self):
            start = self.i
            # optional minus
            if self._peek() == '-':
                self.i += 1
            # int part
            if self._peek() == '0':
                self.i += 1
            elif self._peek() and self._peek().isdigit():
                while self._peek() and self._peek().isdigit():
                    self.i += 1
            else:
                self._error("Invalid number format")

            # fraction
            if self._peek() == '.':
                self.i += 1
                if not self._peek() or not self._peek().isdigit():
                    self._error("Fraction part requires at least one digit")
                while self._peek() and self._peek().isdigit():
                    self.i += 1

            # exponent
            if self._peek() in ('e', 'E'):
                self.i += 1
                if self._peek() in ('+', '-'):
                    self.i += 1
                if not self._peek() or not self._peek().isdigit():
                    self._error("Exponent part requires at least one digit")
                while self._peek() and self._peek().isdigit():
                    self.i += 1

            num_str = self.s[start:self.i]
            try:
                if '.' in num_str or 'e' in num_str or 'E' in num_str:
                    return float(num_str)
                else:
                    return int(num_str)
            except ValueError:
                self._error(f"Invalid numeric literal {num_str!r}")

        # --------------------------------------------------------------- #
        # Utility helpers
        # --------------------------------------------------------------- #
        def _skip_ws(self):
            while self.i < self.n and self.s[self.i] in ' \t\n\r':
                self.i += 1

        def _peek(self):
            return self.s[self.i] if self.i < self.n else None

        def _error(self, msg):
            # Provide a tiny context for easier debugging
            context_start = max(0, self.i - 10)
            context_end = min(self.n, self.i + 10)
            context = self.s[context_start:context_end]
            raise ValueError(f"{msg} at position {self.i}: ...{context}...")

    # --------------------------------------------------------------------- #
    # Run the parser
    # --------------------------------------------------------------------- #
    parser = _Parser(json_str)
    return parser.parse()

