            self._error(f"Unexpected character '{ch}'")

        # ---------- object ----------
        def _object(self):
            self._consume('{')
            obj = {}
            self._skip_ws()
            if self._peek() == '}':
                self._consume('}')
                return obj
            while True:
                self._skip_ws()
                if self._peek() != '"':
                    self._error("Object keys must be strings")
                key = self._string()
                self._skip_ws()
                self._consume(':')
                val = self._value()
                if key in obj:
                    self._error(f"Duplicate key '{key}'")
                obj[key] = val
                self._skip_ws()
                ch = self._peek()
                if ch == '}':
                    self._consume('}')
                    break
                elif ch == ',':
                    self._consume(',')
                else:
                    self._error("Expected ',' or '}' in object")
            return obj

        # ---------- array ----------
        def _array(self):
            self._consume('[')
            arr = []
            self._skip_ws()
            if self._peek() == ']':
                self._consume(']')
                return arr
            while True:
                arr.append(self._value())
                self._skip_ws()
                ch = self._peek()
                if ch == ']':
                    self._consume(']')
                    break
                elif ch == ',':
                    self._consume(',')
                else:
                    self._error("Expected ',' or ']' in array")
            return arr

        # ---------- string ----------
        def _string(self):
            self._consume('"')
            sb = []
            while True:
                if self.i >= self.n:
                    self._error("Unterminated string")
                ch = self.s[self.i]
                if ch == '"':
                    self.i += 1
                    break
                if ch == '\\':
                    self.i += 1
                    if self.i >= self.n:
                        self._error("Unterminated escape sequence")
                    esc = self.s[self.i]
                    self.i += 1
                    if esc == '"':
                        sb.append('"')
                    elif esc == '\\':
                        sb.append('\\')
                    elif esc == '/':
                        sb.append('/')
                    elif esc == 'b':
                        sb.append('\b')
                    elif esc == 'f':
                        sb.append('\f')
                    elif esc == 'n':
                        sb.append('\n')
                    elif esc == 'r':
                        sb.append('\r')
                    elif esc == 't':
                        sb.append('\t')
                    elif esc == 'u':
                        hex_digits = self.s[self.i:self.i+4]
                        if len(hex_digits) != 4 or not all(c in "0123456789abcdefABCDEF" for c in hex_digits):
                            self._error("Invalid Unicode escape")
                        code_point = int(hex_digits, 16)
                        sb.append(chr(code_point))
                        self.i += 4
                    else:
                        self._error(f"Invalid escape character '\\{esc}'")
                elif ord(ch) < 0x20:
                    self._error("Control characters not allowed in strings")
                else:
                    sb.append(ch)
                    self.i += 1
            return ''.join(sb)

        # ---------- number ----------
        def _number(self):
            start = self.i
            # optional minus
            if self.s[self.i] == '-':
                self.i += 1
                if self.i >= self.n:
                    self._error("Invalid number")
            # int part
            if self.s[self.i] == '0':
                self.i += 1
            elif '1' <= self.s[self.i] <= '9':
                while self.i < self.n and self.s[self.i].isdigit():
                    self.i += 1
            else:
                self._error("Invalid number")
            # fraction
            if self.i < self.n and self.s[self.i] == '.':
                self.i += 1
                if self.i >= self.n or not self.s[self.i].isdigit():
                    self._error("Invalid fractional part")
                while self.i < self.n and self.s[self.i].isdigit():
                    self.i += 1
            # exponent
            if self.i < self.n and self.s[self.i] in 'eE':
                self.i += 1
                if self.i < self.n and self.s[self.i] in '+-':
                    self.i += 1
                if self.i >= self.n or not self.s[self.i].isdigit():
                    self._error("Invalid exponent")
                while self.i < self.n and self.s[self.i].isdigit():
                    self.i += 1
            num_str = self.s[start:self.i]
            try:
                if '.' in num_str or 'e' in num_str or 'E' in num_str:
                    return float(num_str)
                else:
                    return int(num_str)
            except ValueError:
                self._error("Number conversion failed")

    return JSONParser(json_str).parse()

def parse_json(json_str: str):
    """
    Parse a JSON string according to RFC 8259 without using the built‑in json module
    or eval. Returns the corresponding Python data structure or raises ValueError
    on any syntax error.
    """
    import re

    # Regular expression for a JSON number (RFC 8259)
    _NUMBER_RE = re.compile(r'-?(?:0|[1-9]\d*)(?:\.\d+)?(?:[eE][+-]?\d+)?')

    # --------------------------------------------------------------------- #
    # Helper class that holds the source string and a mutable index pointer.
    # --------------------------------------------------------------------- #
    class _Parser:
        __slots__ = ("s", "i", "n")

        def __init__(self, s: str):
            self.s = s
            self.i = 0
            self.n = len(s)

        # --------------------------------------------------------------- #
        # Low‑level utilities
        # --------------------------------------------------------------- #
        def peek(self) -> str:
            return self.s[self.i] if self.i < self.n else ""

        def consume(self, expected: str = None) -> str:
            if self.i >= self.n:
                raise ValueError("Unexpected end of input")
            ch = self.s[self.i]
            if expected and ch != expected:
                raise ValueError(f"Expected '{expected}' but found '{ch}' at position {self.i}")
            self.i += 1
            return ch

        def skip_ws(self):
            while self.i < self.n and self.s[self.i] in " \t\n\r":
                self.i += 1

        # --------------------------------------------------------------- #
        # Entry point for parsing any JSON value
        # --------------------------------------------------------------- #
        def parse_value(self):
            self.skip_ws()
            if self.i >= self.n:
                raise ValueError("Unexpected end of input while parsing value")
            ch = self.peek()
            if ch == '"':
                return self.parse_string()
            if ch == '{':
                return self.parse_object()
            if ch == '[':
                return self.parse_array()
            if ch in "-0123456789":
                return self.parse_number()
            if self.s.startswith("true", self.i):
                self.i += 4
                return True
            if self.s.startswith("false", self.i):
                self.i += 5
                return False
            if self.s.startswith("null", self.i):
                self.i += 4
                return None
            raise ValueError(f"Invalid token at position {self.i}")

        # --------------------------------------------------------------- #
        # Object parsing: { "key" : value, ... }
        # --------------------------------------------------------------- #
        def parse_object(self):
            obj = {}
            self.consume('{')
            self.skip_ws()
            if self.peek() == '}':
                self.consume('}')
                return obj
            while True:
                self.skip_ws()
                if self.peek() != '"':
                    raise ValueError(f"Object keys must be strings at position {self.i}")
                key = self.parse_string()
                self.skip_ws()
                self.consume(':')
                value = self.parse_value()
                if key in obj:
                    raise ValueError(f"Duplicate key '{key}' in object at position {self.i}")
                obj[key] = value
                self.skip_ws()
                ch = self.peek()
                if ch == '}':
                    self.consume('}')
                    break
                if ch != ',':
                    raise ValueError(f"Expected ',' or '}}' in object at position {self.i}")
                self.consume(',')
            return obj

        # --------------------------------------------------------------- #
        # Array parsing: [ value, value, ... ]
        # --------------------------------------------------------------- #
        def parse_array(self):
            arr = []
            self.consume('[')
            self.skip_ws()
            if self.peek() == ']':
                self.consume(']')
                return arr
            while True:
                arr.append(self.parse_value())
                self.skip_ws()
                ch = self.peek()
                if ch == ']':
                    self.consume(']')
                    break
                if ch != ',':
                    raise ValueError(f"Expected ',' or ']' in array at position {self.i}")
                self.consume(',')
                self.skip_ws()
            return arr

        # --------------------------------------------------------------- #
        # String parsing with escape handling
        # --------------------------------------------------------------- #
        def parse_string(self):
            self.consume('"')
            sb = []
            while True:
                if self.i >= self.n:
                    raise ValueError("Unterminated string literal")
                ch = self.consume()
                if ch == '"':
                    break
                if ch == '\\':
                    if self.i >= self.n:
                        raise ValueError("Unterminated escape sequence in string")
                    esc = self.consume()
                    if esc == '"':
                        sb.append('"')
                    elif esc == '\\':
                        sb.append('\\')
                    elif esc == '/':
                        sb.append('/')
                    elif esc == 'b':
                        sb.append('\b')
                    elif esc == 'f':
                        sb.append('\f')
                    elif esc == 'n':
                        sb.append('\n')
                    elif esc == 'r':
                        sb.append('\r')
                    elif esc == 't':
                        sb.append('\t')
                    elif esc == 'u':
                        # Expect exactly four hex digits
                        if self.i + 4 > self.n:
                            raise ValueError("Invalid \\u escape (not enough characters)")
                        hex_digits = self.s[self.i:self.i + 4]
                        if not all(c in "0123456789abcdefABCDEF" for c in hex_digits):
                            raise ValueError(f"Invalid \\u escape sequence '\\u{hex_digits}'")
                        code_point = int(hex_digits, 16)
                        sb.append(chr(code_point))
                        self.i += 4
                    else:
                        raise ValueError(f"Invalid escape character '\\{esc}'")
                elif ord(ch) < 0x20:
                    # Control characters are not allowed in JSON strings
                    raise ValueError(f"Invalid control character in string at position {self.i-1}")
                else:
                    sb.append(ch)
            return ''.join(sb)

        # --------------------------------------------------------------- #
        # Number parsing – returns int when possible, else float
        # --------------------------------------------------------------- #
        def parse_number(self):
            start = self.i
            # Use regex to find the longest valid number prefix
            m = _NUMBER_RE.match(self.s, self.i)
            if not m:
                raise ValueError(f"Invalid number at position {self.i}")
            num_str = m.group(0)
            self.i = m.end()
            # Distinguish int vs float
            if any(c in num_str for c in ".eE"):
                try:
                    return float(num_str)
                except ValueError:
                    raise ValueError(f"Invalid float literal '{num_str}'")
            else:
                try:
                    return int(num_str)
                except ValueError:
                    raise ValueError(f"Invalid integer literal '{num_str}'")

    parser = _Parser(json_str)
    result = parser.parse_value()
    parser.skip_ws()
    if parser.i != parser.n:
        raise ValueError(f"Extra data after valid JSON at position {parser.i}")
    return result
